'use strict';

/**
* Convert a symbol alias or shorthand to a Vega symbol mark shape.
*
* @module @stdlib/plot/base/symbol2shape
*
* @example
* var symbol2shape = require( '@stdlib/plot/base/symbol2shape' );
*
* var v = symbol2shape( 'o' );
* // returns 'circle'
*
* v = symbol2shape( 'circle' );
* // returns 'circle'
*
* v = symbol2shape( 'beep' );
* // returns null
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
